#!/usr/bin/env python3
"""patch_site_surfaces_footprints.py -- wall bases finally get dressed.

Lot 0.46.0 -> 0.47.0.

THE PROBLEM YOUR OWN RUN SHOWED. Every invocation of `site_surfaces` on a real
spec reported:

    [warn] LOT_SURFACE_FOOTPRINT_UNKNOWN: no readable footprint for deli,
           garage, gas, pawn -- their wall bases are not offered for dressing

Zero `wall_base` zones, every time, on every spec. `docs/SURFACE_DRESSING.md`
puts the wall seam at HIGH density -- the densest band there is -- and it was
the one band getting nothing at all.

WHY, AND IT IS NOT A MISSING FILE. `lot.merge_gameplay` writes
`b["_footprint"] = gp.get("footprint")` onto the spec IN MEMORY during a Lot
run. Nothing persists the annotated spec. So there is no file anywhere on disk
that has footprints on it, `site_extent.rotated_footprint` returns None for
every building, and no amount of pointing `site_surfaces` at a different path
would have fixed it.

THE FIX. `site_surfaces` calls Lot's own function to fill them in before
computing zones. `--base-dir` defaults to the spec's own directory, which is
where the gameplay files sit for every spec in `lot/specs`, so the common case
needs no flag. Pass an empty string to skip.

MEASURED END TO END ON coldrun_pawn_job, through all four tools:

                      zones   wall_base   placements   at wall seams
    before               79           0        3,745               0
    after                82           4        4,374           1,033

FOUND WHILE DOING IT, AND WORTH KNOWING SEPARATELY: `merge_gameplay` is
ALL-OR-NOTHING on a spec. It raises ValueError on the first building that
declares no `glb` or `scene`, and every building AFTER that one goes
unannotated. On a four-building spec with one geometry-less entry: first
building annotated, raise, three left bare -- which reads on the output as a
site whose walls mostly do not exist, with one warning that does not say how
much it cost.

That is reasonable behaviour for `merge_gameplay`'s own job, which is
assembling geometry, so it is UNCHANGED. `annotate_footprints` instead merges
each building through its own single-entry spec, isolating a refusal to the
building that caused it and naming it. The first draft of this patch called
`merge_gameplay` on the whole spec and had exactly the bug described above;
`test_a_building_with_no_gameplay_file_is_still_reported` is what caught it,
by expecting two wall bases and getting one.

VERIFIED: 41 tests in `test_site_surfaces.py` (32 + 9 new), and the end-to-end
numbers above, run through the real chain with the real GLBs.

    python patch_site_surfaces_footprints.py --check
    python patch_site_surfaces_footprints.py --selftest
    python patch_site_surfaces_footprints.py
    python patch_site_surfaces_footprints.py --revert
"""
