def repo_root(start=None):
    d = os.path.abspath(start or os.path.dirname(os.path.abspath(__file__)))
    for _ in range(8):
        if (os.path.isdir(os.path.join(d, "lot"))
                and os.path.isfile(os.path.join(d, "lot", "site_surfaces.py"))):
            return d
        nd = os.path.dirname(d)
        if nd == d:
            break
        d = nd
    return None


def sha(b):
    return hashlib.sha256(b).hexdigest()


def rd(p):
    with open(p, "rb") as fh:
        return fh.read()


def wr(p, b):
    os.makedirs(os.path.dirname(p), exist_ok=True)
    with open(p, "wb") as fh:
        fh.write(b)


def plan(root):
    rows, ok = [], True
    for rel, d in PAYLOAD.items():
        p = os.path.join(root, rel.replace("/", os.sep))
        exists = os.path.isfile(p)
        if d["kind"] == "new":
            if exists and sha(rd(p)) == d["post_sha"]:
                rows.append((rel, "already-current", True))
            elif exists:
                rows.append((rel, "EXISTS AND DIFFERS - refusing", False))
                ok = False
            else:
                rows.append((rel, f"create {d['post_bytes']} B", True))
            continue
        if not exists:
            rows.append((rel, "MISSING - refusing", False))
            ok = False
            continue
        cur = sha(rd(p))
        if cur == d["post_sha"]:
            rows.append((rel, "already-current", True))
        elif cur == d["pre_sha"]:
            rows.append((rel, f"replace {d['pre_bytes']} -> {d['post_bytes']} B",
                         True))
        else:
            rows.append((rel, f"DRIFT sha {cur[:12]} != {d['pre_sha'][:12]}",
                         False))
            ok = False
    return ok, rows


def show(rows):
    w = max(len(r[0]) for r in rows)
    for rel, msg, good in rows:
        print(f"  {'ok ' if good else 'STOP'}  {rel:<{w}}  {msg}")


def apply(root):
    ok, rows = plan(root)
    show(rows)
    if not ok:
        print("\nREFUSING: nothing written. Resolve the lines marked STOP.")
        return 1
    n = 0
    for rel, d in PAYLOAD.items():
        p = os.path.join(root, rel.replace("/", os.sep))
        if os.path.isfile(p):
            cur = rd(p)
            if sha(cur) == d["post_sha"]:
                continue
            side = p + SIDECAR
            if not os.path.exists(side):
                wr(side, cur)
        wr(p, base64.b64decode(d["b64"]))
        assert sha(rd(p)) == d["post_sha"], rel
        n += 1
    print(f"\nWROTE {n} file(s). Sidecars: *{SIDECAR}")
    print("Next:")
    print("  cd lot; python -m pytest tests -q       # 41 in test_site_surfaces")
    print("Then re-run the chain -- step 2 should now say FOOTPRINTS_MERGED")
    print("instead of FOOTPRINT_UNKNOWN, and the plan should gain about a")
    print("thousand placements at wall seams.")
    return 0


def revert(root):
    n = 0
    for rel, d in PAYLOAD.items():
        p = os.path.join(root, rel.replace("/", os.sep))
        side = p + SIDECAR
        if os.path.exists(side):
            wr(p, rd(side))
            os.remove(side)
            print(f"  reverted {rel}")
            n += 1
        elif d["kind"] == "new" and os.path.isfile(p):
            if sha(rd(p)) == d["post_sha"]:
                os.remove(p)
                print(f"  removed  {rel} (this patch created it)")
                n += 1
            else:
                print(f"  KEPT     {rel} (modified since; not ours to delete)")
    print(f"reverted {n} file(s)")
    return 0


def selftest():
    bad = 0

    def fail(msg):
        nonlocal bad
        print(f"  FAIL  {msg}")
        bad += 1

    print("patch_site_surfaces_footprints selftest")

    for rel, d in PAYLOAD.items():
        b = base64.b64decode(d["b64"])
        if sha(b) != d["post_sha"] or len(b) != d["post_bytes"]:
            fail(f"payload {rel} does not match its recorded hash/size")
    print(f"  ok    {len(PAYLOAD)} payloads decode to their recorded hashes")

    import ast

    def src(rel):
        return base64.b64decode(PAYLOAD[rel]["b64"]).decode("utf-8")

    mod = src("lot/site_surfaces.py")
    tst = src("lot/tests/test_site_surfaces.py")
    tree = ast.parse(mod)
    funcs = {n.name for n in tree.body if isinstance(n, ast.FunctionDef)}
    if "annotate_footprints" not in funcs:
        fail("site_surfaces has no annotate_footprints()")
    if "--base-dir" not in mod:
        fail("the CLI has no --base-dir")
    print("  ok    annotate_footprints and --base-dir are both present")

    # FALSIFICATION: the read must be DELEGATED. Re-implementing it would put
    # the footprint rule in two places, which is the one thing this module is
    # disciplined about.
    if "merge_gameplay" not in mod:
        fail("the footprint read does not go through lot.merge_gameplay")
    # AST, not text: the module's docstring QUOTES `gp.get("footprint")` to
    # explain what lot does, and a substring search called that a
    # reimplementation. This is the third time in this batch that a check
    # written against source text has fired on prose about the source.
    docstrings = set()
    for node in ast.walk(tree):
        if isinstance(node, (ast.Module, ast.FunctionDef, ast.ClassDef,
                             ast.AsyncFunctionDef)):
            d = ast.get_docstring(node, clean=False)
            if d:
                docstrings.add(d)
    reads_key = [n for n in ast.walk(tree)
                 if isinstance(n, ast.Constant) and n.value == "footprint"
                 and n.value not in docstrings]
    if reads_key:
        fail("site_surfaces reads the footprint key itself; that rule belongs "
             "to lot.merge_gameplay and must not exist twice")
    print("  ok    the read is delegated to lot, not reimplemented")

    # The per-building isolation is the fix for a real bug, not a style
    # choice, so it has to be visible in the code and pinned by a test.
    fn = next(n for n in tree.body if isinstance(n, ast.FunctionDef)
              and n.name == "annotate_footprints")
    doc = ast.get_docstring(fn) or ""
    if "ONE BUILDING AT A TIME" not in doc.upper():
        fail("annotate_footprints does not explain the per-building merge")
    if "for b in buildings" not in mod:
        fail("the merge is not per building; one geometry-less entry would "
             "cost every building after it")
    if "test_a_building_with_no_gameplay_file_is_still_reported" not in tst:
        fail("nothing pins the partial-merge bug")
    print("  ok    per-building isolation is in the code and pinned by a test")

    # Opt-in at the API level: `surfaces()` with no base_dir must not rewrite
    # a caller's spec.
    if "test_no_base_dir_leaves_the_spec_exactly_as_it_was" not in tst:
        fail("nothing checks that the merge is opt-in at the API level")
    if "test_a_rotated_building_gets_a_rotated_wall_base" not in tst:
        fail("nothing checks that rotation reaches the wall base")
    print("  ok    opt-in and rotation are both pinned")

    ver = base64.b64decode(PAYLOAD["lot/VERSION"]["b64"])
    if ver != b"Lot 0.47.0":
        fail(f"VERSION payload is {ver!r}")
    ch = src("lot/CHANGELOG.md")
    if not ch.startswith("## [0.47.0]") or "## [0.46.0]" not in ch:
        fail("CHANGELOG is not 0.47.0 on top of 0.46.0")
    print("  ok    Lot 0.47.0 with its entry")

    ref = base64.b64decode(next(iter(PAYLOAD.values()))["b64"])
    mut = bytearray(ref)
    mut[len(mut) // 2] ^= 0x20
    if sha(bytes(mut)) == sha(ref):
        fail("a mutated payload hashed identically")
    else:
        print("  ok    one flipped byte changes the hash")

    print("SELFTEST", "PASSED" if bad == 0 else f"FAILED ({bad})")
    return 1 if bad else 0


def main(argv):
    if "--selftest" in argv:
        return selftest()
    root = None
    if "--root" in argv:
        root = os.path.abspath(argv[argv.index("--root") + 1])
    root = root or repo_root()
    if not root:
        print("Could not find the gabagool_factory root. Pass --root <path>.")
        return 2
    print(f"repo root: {root}")
    if "--revert" in argv:
        return revert(root)
    ok, rows = plan(root)
    if "--check" in argv:
        show(rows)
        print("\n--check only: nothing written."
              + ("" if ok else "  RESOLVE THE STOP LINES FIRST."))
        return 0 if ok else 1
    return apply(root)


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
